INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100001-8100-4000-8000-000000000001', 'HEADING', 0, jsonb_build_object('text', $$Masalah: Motor DC Terlalu Cepat atau Terlalu Lemah$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100001-8100-4000-8000-000000000001', 'PARAGRAPH', 1, jsonb_build_object('text', $$Banyak pemula menghubungkan motor DC langsung ke baterai dan hasilnya tidak terkendali: terlalu cepat untuk robot, atau terlalu lemah untuk menggerakkan beban. Tanpa kendali kecepatan, proyek seperti mobil robot, kipas otomatis, atau pompa air mini sulit berfungsi sebagaimana mestinya.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100001-8100-4000-8000-000000000001', 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Cara Kerja Motor DC dan PWM$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100001-8100-4000-8000-000000000001', 'PARAGRAPH', 3, jsonb_build_object('text', $$Kecepatan motor DC sebanding dengan tegangan rata-rata yang diterimanya. Teknik PWM (Pulse Width Modulation) mengatur tegangan rata-rata dengan menyalakan-mematikan arus ribuan kali per detik. Lebar pulsa (duty cycle) menentukan kecepatan: duty cycle 50 persen berarti setengah kecepatan penuh, 100 persen berarti kecepatan maksimal.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100001-8100-4000-8000-000000000001', 'HEADING', 4, jsonb_build_object('text', $$Alat dan Bahan yang Dibutuhkan$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100001-8100-4000-8000-000000000001', 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Motor DC kecil (3-12 volt)$$, $$Driver motor L298N atau modul transistor MOSFET$$, $$Arduino Uno atau Nano (opsional, bisa pakai potensiometer + NE555)$$, $$Catu daya sesuai tegangan motor (baterai atau adaptor)$$, $$Kabel jumper, breadboard, dan multimeter$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100001-8100-4000-8000-000000000001', 'HEADING', 6, jsonb_build_object('text', $$Langkah: Mengendalikan Kecepatan Motor DC$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100001-8100-4000-8000-000000000001', 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Hubungkan catu daya ke driver motor, jangan ke pin Arduino secara langsung$$, $$Sambungkan motor ke terminal output driver (OUT1-OUT2)$$, $$Hubungkan pin PWM Arduino (misalnya pin 9) ke pin ENA driver$$, $$Unggah program analogWrite(pin, nilai) dengan nilai 0-255 untuk mengatur kecepatan$$, $$Uji bertahap: mulai dari nilai 80, naikkan perlahan sambil amati putaran$$, $$Ukur arus dengan multimeter, pastikan tidak melebihi kemampuan driver$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100001-8100-4000-8000-000000000001', 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Keselamatan$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100001-8100-4000-8000-000000000001', 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$$Jangan hubungkan motor langsung ke pin Arduino: arus motor bisa merusak mikrokontroler$$, $$Driver yang kepanasan menandakan arus berlebih, segera matikan dan cek beban$$, $$Tegangan catu daya tidak boleh melebihi rating motor$$, $$Putaran terbalik tiba-tiba bisa merusak gir, balik arah hanya saat motor berhenti$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100001-8100-4000-8000-000000000001', 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100001-8100-4000-8000-000000000001', 'PARAGRAPH', 11, jsonb_build_object('text', $$Motor berputar halus dari pelan ke cepat mengikuti nilai PWM tanpa bunyi berdecit atau panas berlebih pada driver berarti rangkaian berhasil. Langkah lanjut: tambahkan potensiometer sebagai pengatur manual, atau sensor untuk kendali otomatis seperti robot pengikut garis.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100002-8100-4000-8000-000000000002', 'HEADING', 0, jsonb_build_object('text', $$Masalah: Sate Kambing Bau Prengus dan Keras$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100002-8100-4000-8000-000000000002', 'PARAGRAPH', 1, jsonb_build_object('text', $$Sate kambing rumahan sering gagal: daging alot, bau prengus menyengat, dan bumbu hanya menempel di luar. Padahal sate kambing yang enak seharusnya empuk, gurih sampai ke dalam, dan aromanya menggugah selera tanpa bau menyengat.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100002-8100-4000-8000-000000000002', 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Rahasia Daging Empuk dan Bumbu Meresap$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100002-8100-4000-8000-000000000002', 'PARAGRAPH', 3, jsonb_build_object('text', $$Kunci sate kambing ada tiga: pilih bagian daging yang tepat (paha atau has dalam lebih empuk), marinasi minimal 1 jam agar bumbu meresap ke serat daging, dan bakar dengan api sedang sambil diolesi bumbu olesan agar tidak kering. Nanas parut atau pepaya muda parut mengandung enzim yang melunakkan serat daging secara alami.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100002-8100-4000-8000-000000000002', 'HEADING', 4, jsonb_build_object('text', $$Bahan dan Bumbu$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100002-8100-4000-8000-000000000002', 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$500 gram daging kambing, potong dadu 2-3 cm$$, $$3 sdm nanas parut untuk pelunak alami$$, $$Bumbu halus: 8 bawang merah, 5 bawang putih, 3 cm jahe, 1 sdt ketumbar sangrai, 1/2 sdt jintan$$, $$2 sdm kecap manis, 1 sdm minyak goreng, garam dan gula secukupnya$$, $$Tusuk sate secukupnya, rendam air 30 menit agar tidak gosong$$, $$Pelengkap: lontong, irisan bawang merah, tomat, dan kecap$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100002-8100-4000-8000-000000000002', 'HEADING', 6, jsonb_build_object('text', $$Langkah Membuat Sate Kambing$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100002-8100-4000-8000-000000000002', 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Campur daging dengan nanas parut, diamkan 20 menit, lalu bilas bersih$$, $$Balur daging dengan bumbu halus, kecap, minyak, garam, dan gula; marinasi minimal 1 jam di kulkas$$, $$Tusuk 4-5 potong daging per tusuk, jangan terlalu rapat$$, $$Bakar di atas arang atau grill dengan api sedang$$, $$Olesi sisa bumbu marinasi setiap 2-3 menit sambil dibolak-balik$$, $$Angkat saat permukaan kecokelatan dan sedikit gosong di tepi, sajikan dengan pelengkap$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100002-8100-4000-8000-000000000002', 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100002-8100-4000-8000-000000000002', 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$$Marinasi nanas lebih dari 30 menit membuat daging lembek seperti bubur$$, $$Api terlalu besar membuat luar gosong tapi dalam mentah$$, $$Daging terlalu rapat di tusuk menyebabkan matang tidak merata$$, $$Memakai daging beku yang belum benar-benar cair membuat bumbu sulit meresap$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100002-8100-4000-8000-000000000002', 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Penyajian$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100002-8100-4000-8000-000000000002', 'PARAGRAPH', 11, jsonb_build_object('text', $$Sate kambing berhasil jika daging empuk saat digigit, bumbu terasa sampai ke dalam, dan tidak ada bau prengus. Sajikan selagi panas dengan lontong dan acar bawang. Sisa bumbu marinasi yang sudah dimasak hingga mendidih bisa dipakai sebagai saus cocolan.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100003-8100-4000-8000-000000000003', 'HEADING', 0, jsonb_build_object('text', $$Mengenal Magnesium$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100003-8100-4000-8000-000000000003', 'PARAGRAPH', 1, jsonb_build_object('text', $$Magnesium adalah unsur kimia dengan simbol Mg dan nomor atom 12. Ia termasuk logam alkali tanah golongan 2A, berwujud logam ringan berwarna putih keperakan yang mudah ditempa. Magnesium merupakan unsur kedelapan paling melimpah di kerak bumi dan banyak terdapat di air laut.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100003-8100-4000-8000-000000000003', 'HEADING', 2, jsonb_build_object('text', $$Sifat-sifat Magnesium$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100003-8100-4000-8000-000000000003', 'PARAGRAPH', 3, jsonb_build_object('text', $$Magnesium memiliki massa jenis hanya sekitar dua pertiga aluminium, sehingga digemari untuk paduan ringan. Ia cukup reaktif: mudah bereaksi dengan oksigen, dan pita magnesium tipis dapat dinyalakan dengan korek api. Namun lapisannya yang teroksidasi justru melindunginya dari korosi lebih lanjut.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100003-8100-4000-8000-000000000003', 'HEADING', 4, jsonb_build_object('text', $$Cahaya Terang: Reaksi Pembakaran$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100003-8100-4000-8000-000000000003', 'PARAGRAPH', 5, jsonb_build_object('text', $$Saat dibakar, magnesium bereaksi dengan oksigen membentuk magnesium oksida (2Mg + O2 menjadi 2MgO) sambil memancarkan cahaya putih yang sangat terang dan panas hingga sekitar 3000 derajat Celsius. Cahaya inilah yang dulu dimanfaatkan sebagai lampu kilat (flash) fotografi sebelum digantikan lampu elektronik.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100003-8100-4000-8000-000000000003', 'HEADING', 6, jsonb_build_object('text', $$Magnesium dalam Kehidupan Sehari-hari$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100003-8100-4000-8000-000000000003', 'PARAGRAPH', 7, jsonb_build_object('text', $$Paduan magnesium dipakai pada velg mobil, rangka laptop, dan komponen pesawat karena ringan namun kuat. Serbuk magnesium dipakai dalam kembang api dan suar penyelamat. Menariknya, klorofil, pigmen hijau daun yang menangkap cahaya matahari, memiliki atom magnesium di pusat molekulnya.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100003-8100-4000-8000-000000000003', 'HEADING', 8, jsonb_build_object('text', $$Magnesium bagi Tubuh Manusia$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100003-8100-4000-8000-000000000003', 'PARAGRAPH', 9, jsonb_build_object('text', $$Magnesium adalah mineral penting: membantu kerja otot dan saraf, menjaga irama jantung, serta menguatkan tulang. Kekurangan magnesium bisa menyebabkan kram otot dan kelelahan. Sumber alaminya antara lain kacang-kacangan, biji-bijian, bayam, dan pisang.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100004-8100-4000-8000-000000000004', 'HEADING', 0, jsonb_build_object('text', $$Apa Itu RMS?$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100004-8100-4000-8000-000000000004', 'PARAGRAPH', 1, jsonb_build_object('text', $$RMS adalah singkatan Republik Maluku Selatan, sebuah gerakan separatis yang diproklamasikan pada 25 April 1950 di Ambon oleh Chris Soumokil, mantan jaksa agung Negara Indonesia Timur. Gerakan ini menolak bergabung dengan Republik Indonesia Serikat yang kemudian menjadi negara kesatuan.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100004-8100-4000-8000-000000000004', 'HEADING', 2, jsonb_build_object('text', $$Latar Belakang$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100004-8100-4000-8000-000000000004', 'PARAGRAPH', 3, jsonb_build_object('text', $$Setelah pengakuan kedaulatan 1949, Indonesia berbentuk negara federal (RIS). Sebagian kalangan di Maluku, terutama mantan tentara KNIL asal Ambon, merasa dirugikan oleh rencana pembubaran negara-negara bagian dan pembentukan negara kesatuan. Ketegangan memuncak ketika pasukan APRIS didatangkan ke Ambon.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100004-8100-4000-8000-000000000004', 'HEADING', 4, jsonb_build_object('text', $$Jalannya Pemberontakan$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100004-8100-4000-8000-000000000004', 'PARAGRAPH', 5, jsonb_build_object('text', $$Proklamasi RMS disambut perlawanan bersenjata. Pemerintah Indonesia mengirim ekspedisi militer di bawah pimpinan Alex Kawilarang. Pertempuran sengit terjadi di Ambon dan sekitarnya selama berbulan-bulan pada 1950. Kekuatan RMS yang terbatas akhirnya terdesak ke pedalaman Seram.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100004-8100-4000-8000-000000000004', 'HEADING', 6, jsonb_build_object('text', $$Akhir Pemberontakan$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100004-8100-4000-8000-000000000004', 'PARAGRAPH', 7, jsonb_build_object('text', $$Perlawanan bersenjata RMS di Maluku padam pada awal 1950-an, meski Soumokil sendiri baru tertangkap pada 1963 di Seram. Ia diadili dan dijatuhi hukuman mati yang dilaksanakan pada 1966. Sebagian pengikutnya mengungsi ke Belanda dan melanjutkan gerakan secara politik dari sana.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100004-8100-4000-8000-000000000004', 'HEADING', 8, jsonb_build_object('text', $$Dampak dan Pelajaran Sejarah$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100004-8100-4000-8000-000000000004', 'PARAGRAPH', 9, jsonb_build_object('text', $$Peristiwa RMS menjadi salah satu ujian awal bagi persatuan Indonesia sebagai negara kesatuan. Ia menunjukkan betapa rapuhnya transisi dari negara federal ke negara kesatuan, sekaligus menegaskan tekad pemerintah mempertahankan keutuhan wilayah. Hingga kini, peristiwa ini dipelajari sebagai bagian dari dinamika pembentukan negara Indonesia modern.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100005-8100-4000-8000-000000000005', 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100005-8100-4000-8000-000000000005', 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, kamu diharapkan mampu: menjelaskan pengertian atmosfer, menyebutkan lapisan-lapisan atmosfer beserta cirinya, menjelaskan komposisi udara, dan menganalisis fungsi atmosfer bagi kehidupan di bumi.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100005-8100-4000-8000-000000000005', 'HEADING', 2, jsonb_build_object('text', $$Pengertian Atmosfer$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100005-8100-4000-8000-000000000005', 'PARAGRAPH', 3, jsonb_build_object('text', $$Atmosfer adalah lapisan udara yang menyelimuti bumi, tertahan oleh gaya gravitasi. Ketebalannya mencapai sekitar 1000 kilometer, meski sebagian besar massa udara terkonsentrasi di 10 kilometer terbawah. Tanpa atmosfer, bumi akan seperti bulan: gersang, tanpa cuaca, dan suhunya ekstrem.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100005-8100-4000-8000-000000000005', 'HEADING', 4, jsonb_build_object('text', $$Lapisan-lapisan Atmosfer$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100005-8100-4000-8000-000000000005', 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Troposfer (0-12 km): tempat terjadinya cuaca, suhu turun seiring ketinggian$$, $$Stratosfer (12-50 km): terdapat lapisan ozon yang menyerap radiasi ultraviolet$$, $$Mesosfer (50-80 km): suhu sangat dingin, meteor terbakar di sini$$, $$Termosfer (80-500 km): suhu naik kembali, tempat orbit satelit dan aurora$$, $$Eksosfer (500-1000 km): lapisan terluar, berangsur menyatu dengan ruang angkasa$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100005-8100-4000-8000-000000000005', 'HEADING', 6, jsonb_build_object('text', $$Komposisi Udara$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100005-8100-4000-8000-000000000005', 'PARAGRAPH', 7, jsonb_build_object('text', $$Udara kering tersusun atas nitrogen sekitar 78 persen, oksigen sekitar 21 persen, argon sekitar 0,9 persen, dan sisanya gas-gas lain termasuk karbon dioksida sekitar 0,04 persen. Uap air jumlahnya berubah-ubah, berperan penting dalam pembentukan awan dan hujan.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100005-8100-4000-8000-000000000005', 'HEADING', 8, jsonb_build_object('text', $$Fungsi Atmosfer bagi Kehidupan$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100005-8100-4000-8000-000000000005', 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$$Menyediakan oksigen untuk bernapas dan karbon dioksida untuk fotosintesis$$, $$Melindungi dari radiasi ultraviolet berbahaya melalui lapisan ozon$$, $$Menahan panas matahari sehingga suhu bumi stabil (efek rumah kaca alami)$$, $$Membakar meteor sebelum mencapai permukaan bumi$$, $$Menyebarkan cahaya sehingga langit tampak biru dan senja berwarna$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100005-8100-4000-8000-000000000005', 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100005-8100-4000-8000-000000000005', 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$1. Sebutkan lima lapisan atmosfer beserta ketinggiannya! Kunci: troposfer 0-12 km, stratosfer 12-50 km, mesosfer 50-80 km, termosfer 80-500 km, eksosfer 500-1000 km.$$, $$2. Gas apa yang paling banyak di atmosfer dan berapa persentasenya? Kunci: nitrogen, sekitar 78 persen.$$, $$3. Jelaskan dua fungsi lapisan ozon bagi kehidupan! Kunci: menyerap radiasi UV yang berbahaya bagi kulit dan makhluk hidup; menjaga keseimbangan suhu.$$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100006-8100-4000-8000-000000000006', 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100006-8100-4000-8000-000000000006', 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah belajar materi ini, kamu diharapkan bisa menjelaskan pengertian akhlak, menyebutkan contoh akhlak terpuji (mahmudah) dan akhlak tercela (madzmumah), serta membiasakan akhlak terpuji dalam kehidupan sehari-hari.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100006-8100-4000-8000-000000000006', 'HEADING', 2, jsonb_build_object('text', $$Pengertian Akhlak$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100006-8100-4000-8000-000000000006', 'PARAGRAPH', 3, jsonb_build_object('text', $$Akhlak adalah budi pekerti atau perilaku yang sudah menjadi kebiasaan. Akhlak terbagi dua: akhlak mahmudah yaitu perilaku terpuji yang dicintai Allah, dan akhlak madzmumah yaitu perilaku tercela yang harus dijauhi. Rasulullah diutus untuk menyempurnakan akhlak manusia.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100006-8100-4000-8000-000000000006', 'HEADING', 4, jsonb_build_object('text', $$Contoh Akhlak Terpuji$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100006-8100-4000-8000-000000000006', 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Jujur: berkata dan berbuat sesuai kenyataan$$, $$Amanah: dapat dipercaya menjaga titipan$$, $$Sabar: tabah menghadapi kesulitan$$, $$Syukur: berterima kasih atas nikmat Allah$$, $$Tolong-menolong dan suka berbagi kepada sesama$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100006-8100-4000-8000-000000000006', 'HEADING', 6, jsonb_build_object('text', $$Contoh Akhlak Tercela yang Harus Dihindari$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100006-8100-4000-8000-000000000006', 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Berbohong dan menipu orang lain$$, $$Mencuri dan mengambil hak orang lain$$, $$Sombong dan merendahkan teman$$, $$Dengki atau iri terhadap keberhasilan orang lain$$, $$Pemarah dan suka berkata kasar$$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100006-8100-4000-8000-000000000006', 'HEADING', 8, jsonb_build_object('text', $$Akhlak dalam Kehidupan Sehari-hari$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100006-8100-4000-8000-000000000006', 'PARAGRAPH', 9, jsonb_build_object('text', $$Akhlak terpuji dipraktikkan di mana saja: di rumah dengan berbakti kepada orang tua, di sekolah dengan menghormati guru dan menyayangi teman, serta di masyarakat dengan ramah kepada tetangga. Mulailah dari hal kecil, misalnya mengucapkan salam, tersenyum, dan meminta maaf saat bersalah.$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100006-8100-4000-8000-000000000006', 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal$$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e8100006-8100-4000-8000-000000000006', 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$1. Apa perbedaan akhlak mahmudah dan akhlak madzmumah? Kunci: mahmudah adalah akhlak terpuji, madzmumah adalah akhlak tercela.$$, $$2. Sebutkan tiga contoh akhlak terpuji dalam bergaul dengan teman! Kunci: jujur, tolong-menolong, tidak mengejek, memaafkan (pilih tiga).$$, $$3. Mengapa kita harus menjauhi akhlak tercela? Kunci: karena dibenci Allah, merugikan diri sendiri dan orang lain.$$])));
